def fact(n):
    if n <= 1:
        return 1
    return n * fact(n - 1)
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)
print(fact(6), fib(10))
memo = {}
def fibm(n):
    if n in memo:
        return memo[n]
    if n < 2:
        r = n
    else:
        r = fibm(n - 1) + fibm(n - 2)
    memo[n] = r
    return r
print(fibm(20))
print(fibm(40))
