def qsort(xs):
    if len(xs) <= 1:
        return xs
    p = xs[0]
    lo = []
    eq = []
    hi = []
    for x in xs:
        if x < p:
            lo.append(x)
        elif x > p:
            hi.append(x)
        else:
            eq.append(x)
    return qsort(lo) + eq + qsort(hi)
