def msort(xs):
    if len(xs) <= 1:
        return xs
    m = len(xs) // 2
    left = msort(xs[:m])
    right = msort(xs[m:])
    out = []
    i = 0
    j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            out.append(left[i])
            i += 1
        else:
            out.append(right[j])
            j += 1
    out.extend(left[i:])
    out.extend(right[j:])
    return out
