def bfs(g, s):
    q = [s]
    seen = [s]
    order = []
    while q:
        cur = q.pop(0)
        order.append(cur)
        for nxt in g[cur]:
            if nxt not in seen:
                seen.append(nxt)
                q.append(nxt)
    return order
