def path(g, s, t):
    prev = {}
    q = [s]
    seen = [s]
    while q:
        cur = q.pop(0)
        if cur == t:
            break
        for nxt in g[cur]:
            if nxt not in seen:
                seen.append(nxt)
                prev[nxt] = cur
                q.append(nxt)
    if t not in seen:
        return None
    out = []
    cur = t
    while cur != s:
        out.append(cur)
        cur = prev[cur]
    out.append(s)
    out.reverse()
    return out
