def sieve(n):
    flags = [True] * (n + 1)
    flags[0] = False
    flags[1] = False
    p = 2
    while p * p <= n:
        if flags[p]:
            k = p * p
            while k <= n:
                flags[k] = False
                k += p
        p += 1
    out = []
    for i in range(n + 1):
        if flags[i]:
            out.append(i)
    return out
