def mul_str(a, b):
    res = [0] * (len(a) + len(b))
    for i in range(len(a) - 1, -1, -1):
        for j in range(len(b) - 1, -1, -1):
            res[i + j + 1] += int(a[i]) * int(b[j])
    for i in range(len(res) - 1, 0, -1):
        res[i - 1] += res[i] // 10
        res[i] = res[i] % 10
    out = ''
    for d in res:
        if not (out == '' and d == 0):
            out += str(d)
    if out == '':
        return '0'
    return out
