def rpn(expr):
    st = []
    for tok in expr.split():
        if tok in ['+', '-', '*', '/']:
            b = st.pop()
            a = st.pop()
            if tok == '+':
                st.append(a + b)
            elif tok == '-':
                st.append(a - b)
            elif tok == '*':
                st.append(a * b)
            else:
                st.append(a // b)
        else:
            st.append(int(tok))
    return st.pop()
