class Account:
    def __init__(self, owner):
        self.owner = owner
        self.balance = 0
        self.log = []
    def deposit(self, amt):
        self.balance += amt
        self.log.append('+' + str(amt))
    def withdraw(self, amt):
        if amt > self.balance:
            raise ValueError('insufficient')
        self.balance -= amt
        self.log.append('-' + str(amt))
    def __str__(self):
        return self.owner + ':' + str(self.balance)
