def stats(text):
    words = text.split()
    lens = []
    for w in words:
        lens.append(len(w))
    freq = {}
    for w in words:
        w = w.lower()
        freq[w] = freq.get(w, 0) + 1
    top = sorted(freq.items(), key=lambda p: (-p[1], p[0]))
    return len(words), sum(lens) / len(lens), top[:3]
