def tokenize(s):
    toks = []
    i = 0
    while i < len(s):
        ch = s[i]
        if ch == ' ':
            i += 1
        elif ch >= '0' and ch <= '9':
            j = i
            while j < len(s) and s[j] >= '0' and s[j] <= '9':
                j += 1
            toks.append(('num', int(s[i:j])))
            i = j
        else:
            toks.append(('op', ch))
            i += 1
    return toks
