def render(v, ind):
    pad = ' ' * ind
    if isinstance(v, dict):
        if len(v) == 0:
            return '{}'
        out = '{\n'
        for k in sorted(v):
            out += pad + '  ' + str(k) + ': ' + render(v[k], ind + 2) + '\n'
        return out + pad + '}'
    if isinstance(v, list):
        if len(v) == 0:
            return '[]'
        out = '[\n'
        for x in v:
            out += pad + '  ' + render(x, ind + 2) + '\n'
        return out + pad + ']'
    return str(v)
